window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[176]={"id":"176","numero":176,"titre":"Diarrhée aiguë infectieuse + TIAC","objectifs":[{"id":"176-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une diarrhée","contenu":"<p>La <span class=\"kw-clinique\">diarrhée</span> se définit par l’émission de selles trop <span class=\"kw-clinique\">fréquentes</span>, trop <span class=\"kw-clinique\">abondantes</span>, de consistance anormale — <span class=\"kw-clinique\">liquides</span> ou très <span class=\"kw-clinique\">molles</span>.</p>\n      <p>Le seuil retenu : <span class=\"kw-chiffre\">≥ 3 selles</span> très molles à liquides par jour, <strong>ou</strong> un poids de selles <span class=\"kw-chiffre\">&gt; 250-300 g/24 h</span> en moyenne sur <span class=\"kw-chiffre\">72 h</span>.</p>\n      <p>La <span class=\"kw-def\">durée d’évolution</span> classe ensuite la <span class=\"kw-clinique\">diarrhée</span> :</p>\n      <table >\n        <thead><tr><th>Forme</th><th>Durée d’<span class=\"kw-clinique\">évolution</span></th></tr></thead>\n        <tbody>\n          <tr><td>Aiguë</td><td><span class=\"kw-chiffre\">&lt; 2 semaines</span></td></tr>\n          <tr><td>Prolongée</td><td><span class=\"kw-chiffre\">2 à 4 semaines</span></td></tr>\n          <tr><td>Chronique</td><td><span class=\"kw-chiffre\">&gt; 1 mois</span></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"176-2","rang":"A","rubrique":"Physiopathologie","titre":"Connaître les principales causes, mécanismes et modes de transmission des diarrhées","contenu":"<p>L’étiologie <span class=\"kw-etio\">infectieuse</span> est de loin la plus fréquente. <span class=\"kw-clinique\">Les</span> germes en cause se répartissent en trois familles :</p>\n      <table >\n        <thead><tr><th>Famille</th><th>Principaux germes</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Virale</span></td><td><span class=\"kw-etio\">Norovirus</span> ; <span class=\"kw-etio\">Rotavirus</span> (enfant)</td></tr>\n          <tr><td><span class=\"kw-etio\">Bactérienne</span></td><td><span class=\"kw-etio\">Campylobacter</span> ; <span class=\"kw-etio\">Salmonella</span> ; <span class=\"kw-etio\">Shigella</span> ; <span class=\"kw-etio\">Yersinia</span> ; <span class=\"kw-etio\">E. coli</span> entéro-invasif ou entéro-<span class=\"kw-etio\">hémorragique</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Parasitaire</span></td><td><span class=\"kw-etio\">Giardiose</span> ; <span class=\"kw-etio\">cryptosporidiose</span> ; <span class=\"kw-etio\">Entamoeba histolytica</span></td></tr>\n        </tbody>\n      </table>\n      <p><span class=\"kw-clinique\">Les</span> <span class=\"kw-etio\">parasitoses</span> sont la cause infectieuse <strong>majoritaire</strong> des diarrhées qui durent <span class=\"kw-chiffre\">&gt; 14 jours</span>.</p>\n      <p><strong>Mécanismes</strong> — deux grands modes physiopathologiques s’opposent : le mécanisme <span class=\"kw-def\">entéro-invasif</span> (la bactérie envahit l’épithélium) et le mécanisme <span class=\"kw-def\">sécrétoire / toxinogène</span> (une toxine déclenche une hypersécrétion sans invasion). Ils sous-tendent <span class=\"kw-clinique\">les</span> trois syndromes cliniques.</p>\n      <p><strong>Transmission</strong> — <span class=\"kw-clinique\">eau ou aliments contaminés</span> et <span class=\"kw-clinique\">manuportage</span> d’un individu à l’autre. La saisonnalité oriente : <span class=\"kw-clinique\">pic hivernal</span> pour <span class=\"kw-clinique\">les</span> virus, <span class=\"kw-clinique\">recrudescence estivale</span> pour les bactéries (chaleur, pratiques alimentaires à risque en voyage).</p>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Une <span class=\"kw-alerte\">diarrhée aiguë fébrile</span> ne témoigne pas forcément d’une infection entéro-colique : tout <span class=\"kw-def\">sepsis</span> peut s’accompagner d’une accélération du transit — penser notamment au <span class=\"kw-alerte\">paludisme</span> au retour de voyage.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 170 — <span class=\"kw-clinique\">Paludisme</span> · 175 — Voyage en pays tropical</em></p>","frequence":1},{"id":"176-3","rang":"A","rubrique":"Identifier une urgence","titre":"Identifier les situations à prendre en charge en urgence","contenu":"<div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> Quatre situations imposent une prise en charge immédiate devant une <span class=\"kw-clinique\">diarrhée</span> aiguë.</div>\n      <table >\n        <thead><tr><th>Situation</th><th>Repères</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Sepsis</span></td><td><strong><span class=\"kw-chiffre\">qSOFA</span> <span class=\"kw-chiffre\">≥ 2</span> :</strong> FR <span class=\"kw-chiffre\">≥ 22/min</span> ; PAS <span class=\"kw-chiffre\">≤ 100 mmHg</span> ; <span class=\"kw-def\">Glasgow</span> <span class=\"kw-chiffre\">&lt; 15</span><br><strong>Terrains à risque :</strong> valvulopathie ; sujet âgé ; drépanocytose ; immunodépression (<span class=\"kw-etio\">VIH</span> avec <span class=\"kw-bio\">CD4 &lt; 200</span>, <span class=\"kw-ttt\">chimiothérapie</span>, déficit <span class=\"kw-etio\">congénital</span>)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Déshydratation</span></td><td><strong>Sujets à risque :</strong> nourrisson ; personne âgée dépendante ; patient polymédiqué (<span class=\"kw-ttt\">diurétiques</span>)<br><strong>Pertes :</strong> eau ; sodium ; potassium ; <span class=\"kw-bio\">bicarbonates</span></td></tr>\n          <tr><td>Syndrome occlusif</td><td>Occlusion fonctionnelle du côlon (sans obstacle) : colite grave (<span class=\"kw-etio\">Salmonella</span>, <span class=\"kw-etio\">Shigella</span>, <span class=\"kw-etio\">C. difficile</span>), hypokaliémie, <span class=\"kw-ci\">lopéramide</span><br><strong>CAT :</strong> <span class=\"kw-imagerie\">TDM abdomino-pelvienne injectée</span> pour éliminer une <span class=\"kw-alerte\">urgence</span> chirurgicale</td></tr>\n          <tr><td>Retour de zone d’endémie palustre</td><td>Éliminer un <span class=\"kw-clinique\">accès palustre</span> : <span class=\"kw-bio\">frottis sanguin + goutte épaisse</span> systématiques</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Reconnaître la <span class=\"kw-clinique\">déshydratation</span></strong> — deux compartiments, deux séméiologies :</p>\n      <table >\n        <thead><tr><th><span class=\"kw-clinique\">Déshydratation</span> intracellulaire</th><th><span class=\"kw-clinique\">Déshydratation</span> extracellulaire</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Soif</span></td><td><span class=\"kw-alerte\">Tachycardie, hypotension, oligurie</span> (<span class=\"kw-alerte\">signes de gravité</span>)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Sécheresse des muqueuses</span></td><td><span class=\"kw-clinique\">Pli cutané persistant</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Fièvre, troubles de conscience</span></td><td><span class=\"kw-clinique\">Cernes, yeux creusés</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-def\">Sepsis</span> et <span class=\"kw-def\">choc septique</span> · 170 — <span class=\"kw-clinique\">Paludisme</span> · 152 — <span class=\"kw-etio\">Endocardite</span> infectieuse</em></p>","frequence":1},{"id":"176-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments d’orientation étiologique d’une diarrhée aiguë infectieuse","contenu":"<p>L’orientation étiologique d’une <span class=\"kw-clinique\">diarrhée</span> aiguë infectieuse repose sur une analyse contextuelle et clinique, selon quatre axes :</p>\n      <table >\n        <thead><tr><th>Axe</th><th>Éléments à rechercher</th></tr></thead>\n        <tbody>\n          <tr><td>Contexte favorisant</td><td><strong>Voyage récent :</strong> infection tropicale, parasitose<br><strong><span class=\"kw-ttt\">Antibiothérapie</span> &lt;<span class=\"kw-chiffre\"> 3 mois</span> :</strong> suspicion de <span class=\"kw-etio\">Clostridioides difficile</span><br><strong>Cas groupés :</strong> suspicion de <span class=\"kw-etio\">TIAC</span><br><strong>Contage / contexte épidémique :</strong> gastro-entérite <span class=\"kw-etio\">virale</span></td></tr>\n          <tr><td>Caractéristiques de la <span class=\"kw-clinique\">diarrhée</span></td><td><strong>Durée :</strong> aiguë &lt; 14 j / persistante 14-30 j / chronique &gt;<span class=\"kw-chiffre\"> 1 mois</span><br><strong>Nombre de selles :</strong> sévérité si <span class=\"kw-chiffre\">&gt; 6/jour</span><br><strong>Aspect :</strong> consistance ; présence de <span class=\"kw-clinique\">glaires ou de sang</span> (origine invasive)</td></tr>\n          <tr><td><span class=\"kw-def\">Terrain</span></td><td>Âge avancé ; <span class=\"kw-def\">comorbidités</span> (<span class=\"kw-ci\">insuffisance rénale</span>, <span class=\"kw-etio\">MICI</span>) ; <span class=\"kw-etio\">immunodépression</span></td></tr>\n          <tr><td>Signes associés</td><td><span class=\"kw-clinique\">Fièvre</span> ; <span class=\"kw-clinique\">douleurs abdominales, ténesme, épreintes</span> ; <span class=\"kw-clinique\">vomissements</span> ; signes extradigestifs (<span class=\"kw-clinique\">arthralgies</span>, <span class=\"kw-clinique\">éruption</span>)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 175 — Voyage en pays tropical</em></p>","frequence":0},{"id":"176-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités de diagnostic d’un syndrome cholériforme, dysentérique et gastroentéritique","contenu":"<p>Trois syndromes cliniques structurent le diagnostic d’une <span class=\"kw-clinique\">diarrhée</span> infectieuse. <span class=\"kw-clinique\">Les</span> reconnaître oriente d’emblée le mécanisme, les germes et le risque évolutif.</p>\n      <table >\n        <thead><tr><th></th><th><span class=\"kw-clinique\">Syndrome cholériforme</span></th><th><span class=\"kw-clinique\">Syndrome dysentérique</span></th><th>Syndrome gastro-entéritique</th></tr></thead>\n        <tbody>\n          <tr><td>Mécanisme</td><td><span class=\"kw-def\">Sécrétoire</span> (toxine)</td><td><span class=\"kw-def\">Entéro-invasif</span> (destruction épithéliale)</td><td><span class=\"kw-def\">Entéro-invasif</span> (traversée sans destruction)</td></tr>\n          <tr><td>Siège</td><td>Intestin grêle</td><td>Côlon / iléo-côlon</td><td>Intestin grêle</td></tr>\n          <tr><td>Agents</td><td><span class=\"kw-etio\">Virus</span> (noro, rota, adéno) ; <span class=\"kw-etio\">S. aureus</span>, <span class=\"kw-etio\">B. cereus</span>, <span class=\"kw-etio\">C. perfringens</span> ; <span class=\"kw-etio\">E. coli entéro-toxinogène</span> ; <span class=\"kw-etio\">V. cholerae</span> ; <span class=\"kw-etio\">Cryptosporidium</span></td><td><span class=\"kw-etio\">Shigella</span> ; <span class=\"kw-etio\">E. coli entéro-hémorragique</span> ; <span class=\"kw-etio\">E. coli entéro-invasif</span> ; <span class=\"kw-etio\">Entamoeba histolytica</span></td><td><span class=\"kw-etio\">Campylobacter</span> ; <span class=\"kw-etio\">Salmonella</span> non Typhi ; <span class=\"kw-etio\">Yersinia</span> ; <span class=\"kw-etio\">E. coli entéro-pathogène</span></td></tr>\n          <tr><td>Clinique</td><td><span class=\"kw-clinique\">Diarrhée</span> <span class=\"kw-clinique\">hydrique, aqueuse, profuse</span>, « eau de riz » ; <span class=\"kw-clinique\">vomissements</span> inconstants</td><td>Selles <span class=\"kw-clinique\">afécales, glaireuses, sanglantes</span> ; <span class=\"kw-clinique\">syndrome rectal</span> (épreintes, ténesme, faux besoins)</td><td><span class=\"kw-clinique\">Diarrhée</span> <span class=\"kw-clinique\">banale, aspécifique</span> ; douleurs diffuses ; <span class=\"kw-clinique\">vomissements</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Fièvre</span></td><td><span class=\"kw-clinique\">Absente</span> habituellement</td><td><span class=\"kw-clinique\">Présente</span> — sauf <span class=\"kw-alerte\">amoebose colique = afébrile</span></td><td><span class=\"kw-clinique\">Fréquente</span></td></tr>\n          <tr><td>Risque évolutif</td><td><span class=\"kw-clinique\">Déshydratation</span></td><td><span class=\"kw-alerte\">Sepsis, occlusion, colectasie</span></td><td><span class=\"kw-alerte\">Sepsis, bactériémie</span> (surtout immunodéprimé, drépanocytaire)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Discriminant clé.</strong> Le <span class=\"kw-clinique\">syndrome cholériforme</span> est <strong>afébrile</strong> et hydrique ; le dysentérique est <strong>fébrile et sanglant</strong> — sauf l’<span class=\"kw-alerte\">amoebose</span>, dysentérique mais <strong>sans <span class=\"kw-clinique\">fièvre</span></strong>.</div>","frequence":1},{"id":"176-6","rang":"B","rubrique":"Étiologie","titre":"Connaître les principales étiologies parasitaires de diarrhées","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-etio\">parasitoses</span> dominent les diarrhées qui se prolongent au-delà de <span class=\"kw-chiffre\">14 jours</span>. Quatre situations à connaître :</p>\n      <table >\n        <thead><tr><th>Parasite</th><th>Contexte / particularité</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Giardia intestinalis</span></td><td>Giardiose ; après séjour en zone d’endémie</td></tr>\n          <tr><td><span class=\"kw-etio\">Entamoeba histolytica</span></td><td>Amoebose colique (protozoaire) ; séjour tropical ; <span class=\"kw-clinique\">syndrome dysentérique</span> <strong>afébrile</strong></td></tr>\n          <tr><td><span class=\"kw-etio\">Cryptosporidium</span></td><td><span class=\"kw-clinique\">Diarrhée</span> aqueuse de l’<span class=\"kw-etio\">immunodéprimé</span>, et de l’immunocompétent</td></tr>\n          <tr><td><span class=\"kw-etio\">Microsporidies, isosporidies</span></td><td><span class=\"kw-clinique\">Diarrhée</span> de l’<span class=\"kw-etio\">immunodéprimé</span> (techniques de recherche spécifiques)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> L’<span class=\"kw-alerte\">amoebose</span> donne un <span class=\"kw-clinique\">syndrome dysentérique</span>, mais reste <strong>afébrile</strong> — contrairement aux autres causes invasives.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 175 — Voyage en pays tropical · 285 — <span class=\"kw-clinique\">Diarrhée</span> chronique · 169 — <span class=\"kw-etio\">VIH</span></em></p>","frequence":0},{"id":"176-7","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les principaux examens complémentaires à visée étiologique","contenu":"<p><span class=\"kw-clinique\">Les</span> examens à visée étiologique sont guidés par le tableau clinique :</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Cible / indication</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Coproculture</span></td><td>Recherche de <span class=\"kw-etio\">Salmonella</span>, <span class=\"kw-etio\">Shigella</span>, <span class=\"kw-etio\">Yersinia</span>, <span class=\"kw-etio\">Campylobacter</span> ; à réaliser <strong>avant l’<span class=\"kw-ttt\">antibiothérapie</span></strong> ; indications larges (<span class=\"kw-clinique\">diarrhée</span> fébrile, TIAC fébrile, retour des tropiques, <span class=\"kw-alerte\">signes de gravité</span>, immunodéprimé)</td></tr>\n          <tr><td><span class=\"kw-bio\">Recherche de toxines A/B de C. difficile</span></td><td>Technique <strong>spécifique</strong> à demander explicitement (<span class=\"kw-bio\">PCR</span> ou ELISA) ; non réalisée sur <span class=\"kw-bio\">coproculture</span> standard</td></tr>\n          <tr><td><span class=\"kw-bio\">Hémocultures</span></td><td>Si <span class=\"kw-clinique\">fièvre</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Recherche de virus dans les selles</span></td><td>Épidémies en collectivité ; <span class=\"kw-clinique\">diarrhée</span> de l’immunodéprimé</td></tr>\n          <tr><td><span class=\"kw-bio\">Écouvillon rectal</span></td><td>Si rectite / recto-s<span class=\"kw-chiffre\">igm</span>oïdite : évoquer une <span class=\"kw-clinique\">IST</span> (<span class=\"kw-bio\">sérologie</span> <span class=\"kw-clinique\">syphilis</span>, <span class=\"kw-bio\">PCR</span> Chlamydiae et <span class=\"kw-clinique\">gonocoque</span>, virologie <span class=\"kw-etio\">HSV</span>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Sur <span class=\"kw-bio\">coproculture</span>, <span class=\"kw-alerte\">E. coli non typé, S. aureus et C. albicans</span> correspondent à un <strong>portage sain</strong> — leur présence n’affirme pas l’étiologie. La recherche d’un autre germe (<span class=\"kw-etio\">C. difficile</span> et toxines, EHEC…) doit être <strong>précisée au microbiologiste</strong>.</div>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/clostridioides-difficile-colitis","label":"Radiopaedia : Clostridioides difficile colitis"}]},{"id":"176-8","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’indication d’un examen parasitologique des selles","contenu":"<p>L’<span class=\"kw-bio\">examen parasitologique des selles</span> (<span class=\"kw-bio\">EPS</span>) se réalise <span class=\"kw-chiffre\">3 jours de suite</span> — ou par <span class=\"kw-bio\">PCR multiplex parasites</span>. Ses indications :</p>\n      <ul>\n        <li><strong>Retour de zone d’endémie <span class=\"kw-chiffre\">&lt; 1 mois</span></strong> — recherche de <span class=\"kw-etio\">Giardia intestinalis</span>, <span class=\"kw-etio\">Entamoeba histolytica</span>, <span class=\"kw-etio\">helminthes</span></li>\n        <li><strong>Immunodéprimé</strong> — recherche ciblée de <span class=\"kw-etio\">cryptosporidies</span>, <span class=\"kw-etio\">microsporidies</span>, <span class=\"kw-etio\">isosporidies</span> (techniques spécifiques)</li>\n        <li><strong>Immunocompétent</strong> avec <span class=\"kw-clinique\">diarrhée</span> aqueuse — recherche de <span class=\"kw-etio\">Cryptosporidium</span></li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 175 — Voyage en pays tropical</em></p>","frequence":0},{"id":"176-9","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les principaux examens complémentaires évaluant le retentissement","contenu":"<p>L’évaluation du retentissement cible la <span class=\"kw-clinique\">déshydratation</span> et ses conséquences :</p>\n      <ul>\n        <li><strong>Si <span class=\"kw-clinique\">déshydratation</span></strong> — <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">ionogramme sanguin</span>, <span class=\"kw-bio\">créatininémie</span>, <span class=\"kw-bio\">gazométrie</span></li>\n        <li><strong>Si <span class=\"kw-clinique\">fièvre</span> + <span class=\"kw-clinique\">défense abdominale</span></strong> — <span class=\"kw-imagerie\">TDM abdomino-pelvienne injectée</span></li>\n      </ul>","frequence":1},{"id":"176-10","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications de l’examen endoscopique","contenu":"<p>L’<span class=\"kw-imagerie\">examen endoscopique</span> — <span class=\"kw-imagerie\">recto-sigmoïdoscopie</span>, plus rarement <span class=\"kw-imagerie\">coloscopie</span> — est réalisé avec <strong><span class=\"kw-bio\">biopsies</span></strong>. Indications :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Diarrhée sanglante</span> / <span class=\"kw-clinique\">syndrome dysentérique</span> — coché en <strong><span class=\"kw-chiffre\">1ʳᵉ intention</span></strong> (tombé en annale)</li>\n        <li><span class=\"kw-clinique\">Diarrhée</span> <span class=\"kw-clinique\">persistante</span> sans cause identifiée malgré <span class=\"kw-clinique\">les</span> bilans précédents</li>\n        <li><span class=\"kw-etio\">Immunodépression</span> sans cause identifiée</li>\n      </ul>\n      <p>Elle permet de visualiser des lésions évocatrices — notamment <span class=\"kw-clinique\">les</span> <span class=\"kw-radio\">pseudo-membranes</span> d’une colite à <span class=\"kw-etio\">C. difficile</span>. Devant une rectite ou une recto-s<span class=\"kw-chiffre\">igm</span>oïdite, savoir évoquer une <strong><span class=\"kw-clinique\">IST</span></strong> (<span class=\"kw-etio\">Chlamydiae</span>, <span class=\"kw-etio\">gonocoque</span>, <span class=\"kw-etio\">syphilis</span>, <span class=\"kw-etio\">HSV</span>).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 282 — <span class=\"kw-etio\">MICI</span> · 285 — <span class=\"kw-clinique\">Diarrhée</span> chronique</em></p>","frequence":0},{"id":"176-11","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de prescription d’une réhydratation orale et intraveineuse ; connaître les traitements symptomatiques de la diarrhée aiguë","contenu":"<p><strong>Réhydratation orale</strong> — possible le plus souvent. <span class=\"kw-clinique\">Les</span> <span class=\"kw-ttt\">SRO</span> (solutés de réhydratation orale) contiennent sodium, glucose, potassium et un agent alcalinisant. À défaut : boissons abondantes (eau plate) <strong>associées à une alimentation salée</strong>.</p>\n      <p><strong>Réhydratation intraveineuse</strong> — adaptée à la <span class=\"kw-clinique\">perte de poids</span> et au bilan <span class=\"kw-ttt\">biologique</span> (<span class=\"kw-bio\">kaliémie</span> notamment).</p>\n      <table >\n        <thead><tr><th>Indications de la voie IV</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Déshydratation</span> <span class=\"kw-chiffre\">≥ 8 %</span> du poids ; <span class=\"kw-clinique\">vomissements</span> importants ; <span class=\"kw-alerte\">signes de gravité</span> ; troubles ioniques</td><td>Perfuser <span class=\"kw-chiffre\">50 % des pertes</span> sur <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 premières heures</span>, puis l’autre moitié sur les <span class=\"kw-chiffre\">18 h</span> restantes ; <span class=\"kw-clinique\">surveillance pondérale quotidienne</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Traitements symptomatiques</strong> — l’anti-sécrétoire <span class=\"kw-ttt\">racécadotril</span> (acétorphan) est possible dans tous <span class=\"kw-clinique\">les</span> cas (efficacité peu validée) ; la <span class=\"kw-ttt\">diosmectite</span> et les probiotiques peuvent réduire la durée de la <span class=\"kw-clinique\">diarrhée</span>.</p>","frequence":1},{"id":"176-12","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge symptomatique de la diarrhée","contenu":"<p>La prise en charge symptomatique vise à <strong>réduire l’intensité</strong> de la <span class=\"kw-clinique\">diarrhée</span> sans gêner l’élimination des pathogènes :</p>\n      <ul>\n        <li><strong>Alimentation</strong> — poursuivre <span class=\"kw-clinique\">les</span> apports (<span class=\"kw-clinique\">régime sans résidu</span>) : amidon de riz, pâtes, saccharose, biscuits salés. Éviter les <span class=\"kw-clinique\">repas copieux</span>, le <span class=\"kw-clinique\">lait</span>, les <span class=\"kw-clinique\">crudités</span> et les <span class=\"kw-clinique\">fibres</span>.</li>\n        <li><strong>Anti-sécrétoires et produits inertes</strong> — <span class=\"kw-ttt\">racécadotril</span>, <span class=\"kw-ttt\">diosmectite</span>, probiotiques.</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-ci\">Contre-indication</span>.</strong> <span class=\"kw-clinique\">Les</span> anti-péristaltiques (<span class=\"kw-ci\">lopéramide</span>) sont <strong><span class=\"kw-ci\">contre-indiqués</span></strong> en cas de <span class=\"kw-clinique\">diarrhée</span> sanglante (<span class=\"kw-clinique\">syndrome dysentérique</span>), de <span class=\"kw-clinique\">diarrhée</span> fébrile, ou chez l’enfant <span class=\"kw-alerte\">&lt; 30 mois</span> : ils aggravent les lésions en réduisant la <span class=\"kw-bio\">clairance</span> fécale des pathogènes.</div>","frequence":0},{"id":"176-13","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de l’antibiothérapie","contenu":"<p>L’<span class=\"kw-ttt\">antibiothérapie</span> n’est <strong>pas systématique</strong>. Elle n’est pas indiquée devant un contexte épidémique évoquant une origine <span class=\"kw-etio\">virale</span>, ni devant un tableau cholériforme ou gastro-entéritique non sévère sans <span class=\"kw-def\">terrain</span> à risque.</p>\n      <p><strong>Indications</strong> :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Terrain à risque</span> — âges extrêmes (&lt;<span class=\"kw-chiffre\"> 3 mois</span>, sujet âgé), immunodépression, drépanocytose, valvulopathie, anévrysme de l’aorte</li>\n        <li><span class=\"kw-clinique\">Diarrhée</span> <span class=\"kw-clinique\">dysentérique fébrile</span></li>\n        <li><span class=\"kw-clinique\">Diarrhée</span> cholériforme ou gastro-entéritique <span class=\"kw-clinique\">sévère</span> — T° <span class=\"kw-chiffre\">&gt; 38,5 °C</span> ou selles <span class=\"kw-chiffre\">&gt; 6/jour</span></li>\n      </ul>\n      <p><strong><span class=\"kw-ttt\">Antibiothérapie</span> probabiliste</strong> — d’autant plus efficace si débutée dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">&lt; 48 h</span> ; durée <span class=\"kw-chiffre\">1 à 7 jours</span> en l’absence de <span class=\"kw-clinique\">bactériémie</span> :</p>\n      <ul>\n        <li>Voie orale — <span class=\"kw-ttt\">azithromycine</span> ou <span class=\"kw-ttt\">ciprofloxacine</span> pendant <span class=\"kw-chiffre\">1 à 3 jours</span></li>\n        <li>Voie orale impossible — <span class=\"kw-ttt\">ceftriaxone</span> ± <span class=\"kw-ttt\">métronidazole</span> IV</li>\n        <li>Séjour en zone endémique — ajouter <span class=\"kw-ttt\">métronidazole</span> <span class=\"kw-chiffre\">10 jours</span> (amibiase)</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Rang C — pour information.</strong> Le relais par <span class=\"kw-ttt\">antibiothérapie</span> adaptée dépend du germe : <span class=\"kw-ttt\">azithromycine</span> (<span class=\"kw-etio\">Salmonella</span> non Typhi, <span class=\"kw-etio\">Shigella</span>, <span class=\"kw-etio\">Campylobacter</span>), <span class=\"kw-ttt\">ciprofloxacine</span> (<span class=\"kw-etio\">Yersinia</span>), <span class=\"kw-ttt\">doxycycline</span> (<span class=\"kw-etio\">V. cholerae</span>), <span class=\"kw-ttt\">vancomycine</span> orale (<span class=\"kw-etio\">C. difficile</span>).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 177 — Anti-<span class=\"kw-etio\">infectieux</span></em></p>","frequence":0},{"id":"176-14","rang":"A","rubrique":"Prise en charge","titre":"Connaître les éléments de prévention d’une diarrhée infectieuse","contenu":"<p>La transmission étant essentiellement <span class=\"kw-def\">oro-fécale</span>, la prévention combine hygiène individuelle, hygiène alimentaire, mesures hospitalières et — pour certains germes — <span class=\"kw-ttt\">vaccination</span>.</p>\n      <table >\n        <thead><tr><th>Axe</th><th>Mesures</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Hygiène individuelle</strong></td><td><span class=\"kw-clinique\">Lavage des mains au SHA</span> ; désinfection régulière des sanitaires</td></tr>\n          <tr><td><strong>Hygiène hospitalière</strong></td><td><span class=\"kw-clinique\">Précautions complémentaires contact</span> de <strong>type 1</strong> adaptées au germe — <strong>type 2 si <span class=\"kw-etio\">C. difficile</span></strong> (cf. piège ci-dessous)</td></tr>\n          <tr><td><strong>Hygiène alimentaire</strong></td><td><strong>Respect de la chaîne du froid</strong> ; principe de la <strong>« marche en avant »</strong> (aucun <span class=\"kw-def\">contact</span> entre secteur propre et secteur souillé) ; hygiène sur <span class=\"kw-clinique\">les</span> lieux d’<span class=\"kw-clinique\">abattage</span>, de <span class=\"kw-clinique\">pêche</span> et de <span class=\"kw-clinique\">récolte</span> ; hygiène des transports</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Surveillance</span> des personnels</strong></td><td><span class=\"kw-clinique\">Éviction</span> du personnel de restauration présentant une infection <span class=\"kw-clinique\">cutanée</span>, <span class=\"kw-clinique\">pharyngée</span> ou <span class=\"kw-clinique\">digestive</span></td></tr>\n          <tr><td><strong>Contrôles microbiologiques</strong></td><td>Analyses systématiques des aliments en restauration collective — <span class=\"kw-def\">ARS</span>, <span class=\"kw-def\">DSV</span>, <span class=\"kw-def\">DCCRF</span></td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Vaccination</span></strong></td><td><span class=\"kw-etio\">Rotavirus</span> chez le nourrisson — <span class=\"kw-etio\">rotavirus</span> = 1ʳᵉ cause de <span class=\"kw-clinique\">diarrhée</span> grave avec <span class=\"kw-clinique\">déshydratation</span> chez l’enfant <span class=\"kw-chiffre\">&lt; 5 ans</span> (cf. item 286)</td></tr>\n          <tr><td><strong>Voyageur</strong></td><td>Mesures spécifiques selon la zone — eau, alimentation, prophylaxie antipalustre (cf. item 175)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège — <span class=\"kw-etio\">C. difficile</span>.</strong> <span class=\"kw-clinique\">Les</span> spores résistent aux <span class=\"kw-alerte\">solutions hydro-alcooliques</span> : <strong>lavage des mains au savon doux avant le SHA</strong>, et désinfection des surfaces à l’<strong>eau de Javel</strong> (les détergents classiques sont inefficaces).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 146 — <span class=\"kw-ttt\">Vaccination</span> · 175 — Voyage en pays tropical · 179 — Risques sanitaires liés à l'eau et à l'alimentation</em></p>","frequence":1},{"id":"176-15","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une toxi-infection alimentaire collective","contenu":"<p>Une <span class=\"kw-etio\">toxi-infection alimentaire collective</span> (TIAC) est définie par la survenue d’<strong><span class=\"kw-chiffre\">≥ 2 cas</span></strong> d’une <strong>symptomatologie générale digestive</strong> — typiquement une <span class=\"kw-clinique\">diarrhée</span> d’apparition brutale — rapportable à une <strong>même origine alimentaire probable</strong>.</p>\n      <p><strong>Mode de contamination</strong> — consommation d’aliments contaminés par des bactéries ou leurs toxines :</p>\n      <ul>\n        <li><strong>Toxinogénèse dans l’aliment</strong> — <span class=\"kw-etio\">S. aureus</span> ; toxine thermostable de <span class=\"kw-etio\">B. cereus</span> ; <span class=\"kw-etio\">C. botulinum</span></li>\n        <li><strong>Toxinogénèse dans la lumière digestive</strong> — toxine thermolabile de <span class=\"kw-etio\">B. cereus</span></li>\n      </ul>\n      <p><strong>Aliments le plus souvent en cause</strong> — volaille ; aliments à base d’œufs.</p>\n      <p><strong>Facteurs favorisants</strong> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Non-respect de la chaîne du froid</span></li>\n        <li>Erreurs dans le processus de préparation des aliments</li>\n        <li>Délai trop important entre préparation et consommation</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Maladie à déclaration obl<span class=\"kw-chiffre\">iga</span>toire (<span class=\"kw-def\">MDO</span>).</strong> La TIAC doit être <span class=\"kw-alerte\">déclarée par téléphone à l’<span class=\"kw-def\">ARS</span></span> (ou à défaut au service vétérinaire d’hygiène alimentaire) ; <span class=\"kw-clinique\">les</span> restes alimentaires des <span class=\"kw-chiffre\">3 derniers jours</span> sont conservés au <strong>frigo</strong> (jamais au congélateur) pour analyse microbiologique.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 179 — Risques sanitaires liés à l'eau et à l'alimentation</em></p>","frequence":0},{"id":"176-16","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir identifier les situations à prendre en charge en urgence","contenu":"<p>Cet objectif complète l’identification des urgences sous l’angle des <strong>critères d’<span class=\"kw-alerte\">hospitalisation</span></strong> :</p>\n      <ul>\n        <li>Âge <span class=\"kw-chiffre\">&lt; 3 mois</span></li>\n        <li><span class=\"kw-clinique\">Déshydratation</span> <span class=\"kw-chiffre\">&gt; 8 %</span> du poids, <span class=\"kw-alerte\">collapsus</span>, signes de <span class=\"kw-def\">sepsis</span>, syndrome occlusif</li>\n        <li><span class=\"kw-clinique\">Diarrhée</span> <span class=\"kw-clinique\">fébrile</span> au retour d’un pays d’endémie palustre</li>\n        <li><span class=\"kw-clinique\">Vomissements</span> rendant la réhydratation orale impossible</li>\n        <li><span class=\"kw-alerte\">Décompensation</span> d’une <span class=\"kw-def\">comorbidité</span> ; <span class=\"kw-def\">isolement</span> ou milieu social défavorisé</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Repère.</strong> <span class=\"kw-clinique\">Les</span> quatre situations d’<span class=\"kw-alerte\">urgence</span> à reconnaître d’emblée — <span class=\"kw-def\">sepsis</span>, <span class=\"kw-clinique\">déshydratation</span>, <span class=\"kw-alerte\">syndrome occlusif</span>, <span class=\"kw-alerte\">retour de zone palustre</span> — sont détaillées dans l’objectif « Identifier les situations à prendre en charge en urgence ».</div>","frequence":0},{"id":"176-17","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître la prescription d’une réhydratation orale et intraveineuse ; connaître les traitements symptomatiques de la diarrhée aiguë","contenu":"<p>En situation d’<span class=\"kw-alerte\">urgence</span>, la prescription de réhydratation se décide sur la gravité :</p>\n      <ul>\n        <li><strong>Voie orale</strong> — <span class=\"kw-ttt\">SRO</span> dès que possible (sodium, glucose, potassium, agent alcalinisant), associés à une alimentation salée</li>\n        <li><strong>Voie IV</strong> — indiquée si <span class=\"kw-clinique\">déshydratation</span> <span class=\"kw-chiffre\">≥ 8 %</span> du poids, <span class=\"kw-clinique\">vomissements</span> importants, <span class=\"kw-alerte\">signes de gravité</span> ou <span class=\"kw-bio\">troubles ioniques</span> ; perfusion adaptée à la <span class=\"kw-clinique\">perte de poids</span> et au bilan <span class=\"kw-ttt\">biologique</span> (<span class=\"kw-bio\">kaliémie</span>)</li>\n      </ul>\n      <p><strong>Protocole IV</strong> — perfuser <span class=\"kw-chiffre\">50 % des pertes</span> sur <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 premières heures</span>, puis l’autre moitié sur les <span class=\"kw-chiffre\">18 h</span> restantes, avec <span class=\"kw-clinique\">surveillance pondérale quotidienne</span>. Les traitements symptomatiques (<span class=\"kw-ttt\">racécadotril</span>, <span class=\"kw-ttt\">diosmectite</span>) complètent la prise en charge.</p>\n      <div class=\"callout callout-info\"><strong>Repère.</strong> Le détail complet de la réhydratation et des traitements symptomatiques figure dans l’objectif « Connaître <span class=\"kw-clinique\">les</span> principes de prescription d’une réhydratation orale et intraveineuse… ».</div>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p>Quatre situations imposent une prise en charge immédiate devant une <span class=\"kw-clinique\">diarrhée</span> aiguë ; <span class=\"kw-clinique\">les</span> repérer conditionne le <span class=\"kw-def\">pronostic</span>.</p><p><strong><span class=\"kw-def\">Sepsis</span></strong></p><ul><li><span class=\"kw-def\">qSOFA ≥ 2</span> : FR <span class=\"kw-chiffre\">≥ 22/min</span>, PAS <span class=\"kw-chiffre\">≤ 100 mmHg</span>, <span class=\"kw-def\">Glasgow</span> <span class=\"kw-chiffre\">&lt; 15</span></li><li><span class=\"kw-def\">Terrain</span> à risque : <span class=\"kw-etio\">valvulopathie</span>, <span class=\"kw-etio\">sujet âgé</span>, <span class=\"kw-etio\">drépanocytose</span>, <span class=\"kw-etio\">immunodépression</span> (<span class=\"kw-etio\">VIH</span> avec <span class=\"kw-bio\">CD4 &lt; 200</span>)</li></ul><p><strong><span class=\"kw-clinique\">Déshydratation</span> <span class=\"kw-chiffre\">≥ 8 %</span> du poids</strong></p><ul><li>Sujets à risque : <span class=\"kw-etio\">nourrisson</span>, <span class=\"kw-etio\">personne âgée dépendante</span>, <span class=\"kw-etio\">polymédiqué</span> (<span class=\"kw-ttt\">diurétiques</span>)</li><li>Pertes : <span class=\"kw-clinique\">eau</span>, <span class=\"kw-bio\">sodium</span>, <span class=\"kw-bio\">potassium</span>, <span class=\"kw-bio\">bicarbonates</span></li><li>Impose une <span class=\"kw-ttt\">réhydratation IV</span></li></ul><p><strong><span class=\"kw-alerte\">Syndrome occlusif</span></strong></p><ul><li>Occlusion fonctionnelle du côlon (sans obstacle) : <span class=\"kw-etio\">colite grave</span> (<span class=\"kw-etio\">Salmonella</span>, <span class=\"kw-etio\">Shigella</span>, <span class=\"kw-etio\">C. difficile</span>), <span class=\"kw-bio\">hypokaliémie</span>, <span class=\"kw-ci\">lopéramide</span></li><li><span class=\"kw-imagerie\">TDM abdomino-pelvienne injectée</span> pour éliminer une <span class=\"kw-alerte\">péritonite / perforation</span> ou une occlusion</li></ul><p><strong>Retour de zone d’endémie palustre</strong></p><ul><li>Éliminer un <span class=\"kw-alerte\">accès palustre</span> : <span class=\"kw-bio\">frottis sanguin</span> + <span class=\"kw-bio\">goutte épaisse</span> systématiques</li><li>La <span class=\"kw-etio\">fièvre typhoïde</span> ne donne une <span class=\"kw-clinique\">diarrhée</span> qu’en phase d’état</li></ul><p><strong>Délais clés</strong></p><ul><li><span class=\"kw-ttt\">Antibiothérapie</span> probabiliste d’autant plus efficace si débutée <span class=\"kw-chiffre\">&lt; 48 h</span></li><li><span class=\"kw-ttt\">Réhydratation IV</span> : <span class=\"kw-chiffre\">50 % des pertes en 6 h</span>, puis l’autre moitié sur <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">18 h</span> restantes</li><li><span class=\"kw-bio\">Frottis + goutte épaisse</span> en <span class=\"kw-alerte\">urgence</span> au retour de zone palustre</li></ul>","hospit":"<p><span class=\"kw-alerte\">Hospitalisation</span> devant tout <span class=\"kw-alerte\">signe de gravité</span>, <span class=\"kw-def\">terrain</span> fragile ou impossibilité de <span class=\"kw-ttt\">réhydratation orale</span>.</p><p><strong>Critères d’<span class=\"kw-alerte\">hospitalisation</span></strong></p><ul><li>Âge <span class=\"kw-chiffre\">&lt; 3 mois</span></li><li><span class=\"kw-clinique\">Déshydratation</span> <span class=\"kw-chiffre\">&gt; 8 %</span> du poids, <span class=\"kw-alerte\">collapsus</span>, signes de <span class=\"kw-def\">sepsis</span>, <span class=\"kw-alerte\">syndrome occlusif</span></li><li><span class=\"kw-clinique\">Diarrhée</span> <span class=\"kw-clinique\">fébrile</span> au retour d’un pays d’endémie palustre</li><li><span class=\"kw-clinique\">Vomissements</span> rendant la <span class=\"kw-ttt\">réhydratation orale</span> impossible</li><li><span class=\"kw-alerte\">Décompensation</span> d’une <span class=\"kw-def\">comorbidité</span>, <span class=\"kw-def\">isolement</span> ou milieu social défavorisé</li></ul><p><strong>Orientation spécialisée</strong></p><ul><li>Persistance <span class=\"kw-chiffre\">&gt; 1 semaine</span> → avis gastro-entérologique (<span class=\"kw-etio\">MICI</span>, <span class=\"kw-etio\">colite microscopique</span>, <span class=\"kw-etio\">maladie cœliaque</span>)</li><li>Plusieurs épisodes/an → avis spécialisé (<span class=\"kw-etio\">déficit immunitaire</span> possible)</li><li>Infection à <span class=\"kw-etio\">C. difficile</span> sévère ou <span class=\"kw-def\">terrain</span> fragile → <span class=\"kw-alerte\">hospitalisation</span> avec <span class=\"kw-ttt\">précautions complémentaires contact</span></li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Sepsis</span> — <span class=\"kw-def\">qSOFA ≥ 2</span> : FR <span class=\"kw-chiffre\">≥ 22/min</span>, PAS <span class=\"kw-chiffre\">≤ 100 mmHg</span>, <span class=\"kw-def\">Glasgow</span> <span class=\"kw-chiffre\">&lt; 15</span></li><li><span class=\"kw-alerte\">Déshydratation extracellulaire</span> : <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">hypotension</span>, <span class=\"kw-clinique\">oligurie</span></li><li><span class=\"kw-alerte\">Collapsus</span></li><li><span class=\"kw-clinique\">Déshydratation</span> <span class=\"kw-chiffre\">≥ 8 %</span> du poids du corps</li><li><span class=\"kw-alerte\">Syndrome occlusif</span> (arrêt des matières et des gaz)</li><li><span class=\"kw-alerte\">Défense abdominale</span> → complication (<span class=\"kw-alerte\">perforation</span>)</li><li><span class=\"kw-clinique\">Fièvre</span> + <span class=\"kw-alerte\">défense abdominale</span> → <span class=\"kw-imagerie\">TDM abdomino-pelvienne injectée</span></li><li><span class=\"kw-alerte\">Colite pseudo-membraneuse</span> à <span class=\"kw-etio\">C. difficile</span> : <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">AEG</span>, <span class=\"kw-clinique\">diarrhée abondante</span>, <span class=\"kw-bio\">hyperleucocytose</span></li><li><span class=\"kw-alerte\">Mégacôlon toxique</span>, <span class=\"kw-alerte\">colectasie</span>, <span class=\"kw-alerte\">perforation colique</span> (forme sévère à <span class=\"kw-etio\">C. difficile</span>, <span class=\"kw-def\">mortalité</span> <span class=\"kw-chiffre\">~50 %</span>)</li><li><span class=\"kw-alerte\">SHU</span> par <span class=\"kw-etio\">E. coli entéro-hémorragique</span> (<span class=\"kw-def\">toxine shiga-like</span>)</li><li><span class=\"kw-def\">Terrain</span> à risque de forme grave / <span class=\"kw-alerte\">bactériémie</span> : <span class=\"kw-etio\">nourrisson</span>, <span class=\"kw-etio\">sujet âgé</span>, <span class=\"kw-etio\">immunodéprimé</span>, <span class=\"kw-etio\">drépanocytaire</span>, <span class=\"kw-etio\">valvulopathie</span></li></ul>","principes":"<p><strong><span class=\"kw-clinique\">Diarrhée</span> sécrétoire :</strong> traitement dominé par la <span class=\"kw-ttt\">réhydratation hydroélectrolytique</span>.<br><strong>Diarrhée invasive :</strong> <span class=\"kw-ttt\">réhydratation</span> + <span class=\"kw-ttt\">antibiothérapie</span> le plus souvent.</p><p><strong><span class=\"kw-ttt\">Réhydratation orale</span> (1ʳᵉ intention)</strong></p><ul><li><span class=\"kw-ttt\">SRO</span> (solutés de réhydratation orale) : <span class=\"kw-bio\">sodium</span>, <span class=\"kw-bio\">glucose</span>, <span class=\"kw-bio\">potassium</span>, agent alcalinisant</li><li>À défaut : boissons abondantes (eau plate) + <strong>alimentation salée</strong></li></ul><p><strong><span class=\"kw-ttt\">Réhydratation IV</span></strong></p><ul><li>Indications : <span class=\"kw-clinique\">déshydratation</span> <span class=\"kw-chiffre\">≥ 8 %</span> du poids, <span class=\"kw-clinique\">vomissements</span> importants, <span class=\"kw-alerte\">signes de gravité</span>, <span class=\"kw-bio\">troubles ioniques</span></li><li>Modalités : <span class=\"kw-chiffre\">50 % des pertes</span> sur <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 premières heures</span>, puis l’autre moitié sur les <span class=\"kw-chiffre\">18 h</span> restantes</li><li>Adaptée à la <span class=\"kw-clinique\">perte de poids</span> et au bilan (<span class=\"kw-bio\">kaliémie</span>)</li></ul><p><strong>Traitement symptomatique</strong></p><ul><li><span class=\"kw-clinique\">Régime sans résidu</span> : amidon de riz, pâtes, saccharose, biscuits salés ; éviter repas copieux, lait, crudités, fibres</li><li>Anti-sécrétoire : <span class=\"kw-ttt\">racécadotril</span> (acétorphan)</li><li>Produits inertes : <span class=\"kw-ttt\">diosmectite</span>, probiotiques</li></ul><p><strong><span class=\"kw-ci\">Lopéramide</span> <span class=\"kw-ci\">contre-indiqué</span></strong></p><ul><li>CI si <span class=\"kw-clinique\">diarrhée sanglante</span> (<span class=\"kw-clinique\">syndrome dysentérique</span>), <span class=\"kw-clinique\">diarrhée fébrile</span>, ou âge <span class=\"kw-chiffre\">&lt; 30 mois</span></li><li>Risque : aggraver <span class=\"kw-clinique\">les</span> lésions en réduisant la <span class=\"kw-bio\">clairance</span> fécale des pathogènes</li></ul><p><strong><span class=\"kw-ttt\">Antibiothérapie</span> probabiliste</strong></p><ul><li>Non systématique : inutile si contexte épidémique <span class=\"kw-etio\">viral</span> ou tableau cholériforme / gastro-entéritique non sévère sans <span class=\"kw-def\">terrain</span> à risque</li><li>Indications : <span class=\"kw-etio\">terrain à risque</span>, <span class=\"kw-clinique\">diarrhée dysentérique fébrile</span>, forme <span class=\"kw-clinique\">sévère</span> (T° <span class=\"kw-chiffre\">&gt; 38,5 °C</span> ou selles <span class=\"kw-chiffre\">&gt; 6/jour</span>)</li><li>Voie orale : <span class=\"kw-ttt\">azithromycine</span> ou <span class=\"kw-ttt\">ciprofloxacine</span> <span class=\"kw-chiffre\">1 à 3 jours</span> ; durée totale <span class=\"kw-chiffre\">1 à 7 jours</span></li><li>Voie orale impossible : <span class=\"kw-ttt\">ceftriaxone</span> ± <span class=\"kw-ttt\">métronidazole</span> IV</li><li>Séjour en zone endémique : ajouter <span class=\"kw-ttt\">métronidazole</span> <span class=\"kw-chiffre\">10 jours</span> (amibiase)</li></ul><p><strong>Infection à <span class=\"kw-etio\">C. difficile</span></strong></p><ul><li>Arrêt de l’<span class=\"kw-ttt\">ATB responsable</span> si possible, hydratation, <span class=\"kw-ci\">lopéramide</span> <span class=\"kw-ci\">contre-indiqué</span></li><li>Non sévère (domicile) : <span class=\"kw-ttt\">vancomycine orale</span> <span class=\"kw-chiffre\">10 jours</span> (alternatives : <span class=\"kw-ttt\">fidaxomicine</span> ou <span class=\"kw-ttt\">métronidazole</span>)</li><li>Sévère / <span class=\"kw-def\">terrain</span> fragile : <span class=\"kw-alerte\">hospitalisation</span>, <span class=\"kw-ttt\">vancomycine orale</span> + <span class=\"kw-ttt\">métronidazole IV</span> <span class=\"kw-chiffre\">10 jours</span>, <span class=\"kw-ttt\">précautions contact</span> (savon doux puis SHA, surfaces à la <span class=\"kw-ttt\">Javel</span>)</li><li><span class=\"kw-alerte\">Colectasie / mégacôlon toxique / perforation</span> : <span class=\"kw-ttt\">colectomie subtotale</span></li></ul><p><strong><span class=\"kw-ttt\">Antibiothérapie</span> adaptée — rang C</strong></p><ul><li><span class=\"kw-etio\">Salmonella</span> non Typhi / <span class=\"kw-etio\">Shigella</span> : <span class=\"kw-ttt\">azithromycine</span> <span class=\"kw-chiffre\">3 j</span></li><li><span class=\"kw-etio\">Campylobacter</span> : <span class=\"kw-ttt\">azithromycine</span> <span class=\"kw-chiffre\">1 à 3 j</span></li><li><span class=\"kw-etio\">Yersinia</span> : <span class=\"kw-ttt\">ciprofloxacine</span> <span class=\"kw-chiffre\">7 j</span></li><li><span class=\"kw-etio\">Vibrio cholerae</span> : <span class=\"kw-ttt\">doxycycline</span> <span class=\"kw-chiffre\">1 j</span></li><li><span class=\"kw-etio\">C. difficile</span> toxinogène : <span class=\"kw-ttt\">métronidazole</span> (ville, forme non sévère) ou <span class=\"kw-ttt\">vancomycine PO</span> (hôpital), <span class=\"kw-chiffre\">10 j</span></li></ul>","suivi":"<p><strong><span class=\"kw-clinique\">Évolution</span> :</strong> régression spontanée ou sous traitement symptomatique en <span class=\"kw-chiffre\">&lt; 3 jours</span> dans la majorité des cas ; <strong><span class=\"kw-def\">surveillance</span> pondérale quotidienne</strong> sous réhydratation.</p><p><strong><span class=\"kw-def\">Surveillance</span></strong></p><ul><li><span class=\"kw-clinique\">Surveillance pondérale quotidienne</span> sous réhydratation</li><li><span class=\"kw-ttt\">Réhydratation IV</span> adaptée à la perte de poids et au bilan (<span class=\"kw-bio\">kaliémie</span>)</li><li>Infection à <span class=\"kw-etio\">C. difficile</span> : <strong>pas</strong> de contrôle de la <span class=\"kw-bio\">coproculture</span> en fin de traitement</li></ul><p><strong>Récidives à <span class=\"kw-etio\">C. difficile</span> (<span class=\"kw-chiffre\">10-20 %</span>)</strong></p><ul><li><span class=\"kw-ttt\">Vancomycine orale</span> ou <span class=\"kw-ttt\">fidaxomicine</span> <span class=\"kw-chiffre\">10 jours</span></li><li>2ⁿᵈᵉ récidive (3ᵉ épisode) → <span class=\"kw-ttt\">transplantation de microbiote fécal</span> (<span class=\"kw-chiffre\">&gt; 85 %</span> de succès)</li></ul><p><strong><span class=\"kw-def\">TIAC</span> — maladie à déclaration obl<span class=\"kw-chiffre\">iga</span>toire</strong></p><ul><li>Définition : <span class=\"kw-chiffre\">≥ 2 cas</span> d’une symptomatologie digestive de même origine alimentaire probable</li><li><span class=\"kw-ttt\">Déclaration</span> par téléphone au médecin inspecteur de l’<span class=\"kw-def\">ARS</span> (ou service vétérinaire d’hygiène alimentaire)</li><li>Conserver <span class=\"kw-clinique\">les</span> restes alimentaires des <span class=\"kw-chiffre\">3 derniers jours</span> au <strong>frigo</strong> (jamais au congélateur) ; prélèvements de selles ± <span class=\"kw-clinique\">vomissements</span></li></ul><p><strong>Drapeaux de <span class=\"kw-def\">suivi</span></strong></p><ul><li>Persistance <span class=\"kw-chiffre\">&gt; 1 semaine</span> → avis gastro-entérologique</li><li>Sujet <span class=\"kw-chiffre\">&gt; 75 ans</span> : pic de <span class=\"kw-alerte\">mortalité à 8-10 jours</span> (hypoperfusion post-<span class=\"kw-clinique\">déshydratation</span>)</li></ul>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/clostridioides-difficile-colitis","label":"radiopaedia.org"}],"cards":[{"i":"719bf2865909","n":176,"o":"176-1","u":"Définition","t":"Connaître la définition d’une diarrhée","q":"Comment définit-on la diarrhée d'un point de vue clinique ?","a":"<p>La diarrhée se définit par l'émission de selles :</p><ul><li>trop <strong>fréquentes</strong></li><li>trop <strong>abondantes</strong></li><li>de consistance <strong>anormale</strong> (liquides ou très molles).</li></ul>"},{"i":"9d23e5fa62a5","n":176,"o":"176-1","u":"Définition","t":"Connaître la définition d’une diarrhée","q":"Quels sont les seuils quantitatifs permettant de diagnostiquer une diarrhée ?","a":"<p>Les seuils retenus pour le diagnostic de diarrhée sont :</p><ul><li><strong>≥ 3 selles très molles à liquides par jour</strong>.</li><li>ou un <strong>poids de selles > 250-300 g/24 h</strong> (en moyenne sur 72h).</li></ul>"},{"i":"c77845b7cca0","n":176,"o":"176-1","u":"Définition","t":"Connaître la définition d’une diarrhée","q":"Quelles sont les différentes classifications de la diarrhée selon sa durée d'évolution ?","a":"<p>La diarrhée est classée selon sa durée d'évolution :</p><ul><li><strong>Diarrhée aiguë</strong> : durée <strong>< 2 semaines</strong>.</li><li><strong>Diarrhée prolongée</strong> : durée comprise entre <strong>2 et 4 semaines</strong>.</li><li><strong>Diarrhée chronique</strong> : durée <strong>> 1 mois</strong>.</li></ul>"},{"i":"170399ed24c4","n":176,"o":"176-11","u":"Prise en charge","t":"Connaître les principes de prescription d’une réhydratation orale et intraveineuse ; connaître les traitements symptomatiques de la diarrhée aiguë","q":"Quelles sont les indications de la réhydratation intraveineuse dans la diarrhée aiguë infectieuse, et comment celle-ci est-elle schématisée ?","a":"<p>Les indications de la réhydratation intraveineuse sont :</p><ul><li>Une <strong>déshydratation ≥ 8 % du poids</strong>.</li><li>Des <strong>vomissements importants</strong>.</li><li>Des <strong>signes de gravité</strong>.</li><li>Des <strong>troubles ioniques</strong> (notamment de la kaliémie).</ul><p>Les modalités sont de perfuser <strong>50 % des pertes</strong> sur les <strong>6 premières heures</strong>, puis l’autre moitié sur les <strong>18 heures restantes</strong>, avec une surveillance pondérale quotidienne.</p>"},{"i":"1eb7368aca95","n":176,"o":"176-11","u":"Prise en charge","t":"Connaître les principes de prescription d’une réhydratation orale et intraveineuse ; connaître les traitements symptomatiques de la diarrhée aiguë","q":"Quels sont les principes de prescription de la réhydratation orale (SRO) dans la diarrhée aiguë infectieuse et les alternatives si les SRO ne sont pas disponibles ?","a":"<p>La réhydratation orale est possible le plus souvent, via des SRO (Solutés de Réhydratation Orale) contenant du <strong>sodium</strong>, du <strong>glucose</strong>, du <strong>potassium</strong> et un <strong>agent alcalinisant</strong>. À défaut de SRO, il faut proposer des <strong>boissons abondantes</strong> (eau plate) associées à une <strong>alimentation salée</strong>.</p>"},{"i":"ca414da5d286","n":176,"o":"176-11","u":"Prise en charge","t":"Connaître les principes de prescription d’une réhydratation orale et intraveineuse ; connaître les traitements symptomatiques de la diarrhée aiguë","q":"Quels sont les traitements symptomatiques de la diarrhée aiguë ?","a":"<p>Les traitements symptomatiques possibles sont :</p><ul><li>L'anti-sécrétoire <strong>racécadotril</strong> (acétorphan), possible dans tous les cas (efficacité peu validée).</li><li>La <strong>diosmectite</strong>.</li><li>Les <strong>probiotiques</strong>.</ul><p>Ces deux derniers peuvent réduire la durée de la diarrhée.</p>"},{"i":"30291e73610a","n":176,"o":"176-12","u":"Prise en charge","t":"Connaître les principes de la prise en charge symptomatique de la diarrhée","q":"Quels médicaments symptomatiques sont recommandés dans la prise en charge de la diarrhée aiguë infectieuse et TIAC ?","a":"<ul><li>Les <strong>anti-sécrétoires</strong> tel que le <strong>racécadotril</strong></li><li>Les <strong>produits inertes</strong> comme la <strong>diosmectite</strong></li><li>Les <strong>probiotiques</strong></li></ul>"},{"i":"c020d2098f15","n":176,"o":"176-12","u":"Prise en charge","t":"Connaître les principes de la prise en charge symptomatique de la diarrhée","q":"Quels sont les aliments à privilégier ou à proposer dans le cadre d'un régime sans résidu pour une diarrhée aiguë infectieuse et TIAC ?","a":"<ul><li><strong>Amidon de riz</strong></li><li><strong>Pâtes</strong></li><li><strong>Saccharose</strong></li><li><strong>Biscuits salés</strong></li></ul>"},{"i":"c686528ca4b9","n":176,"o":"176-12","u":"Prise en charge","t":"Connaître les principes de la prise en charge symptomatique de la diarrhée","q":"Pourquoi les anti-péristaltiques sont-ils contre-indiqués dans certaines situations de diarrhée aiguë infectieuse et TIAC ?","a":"<p>Ils sont contre-indiqués car ils risquent d'<strong>aggraver les lésions</strong> en réduisant la <strong>clairance fécale des pathogènes</strong>, ce qui peut prolonger l'infection ou augmenter la toxicité des bactéries.</p>"},{"i":"d6689ac6dea2","n":176,"o":"176-12","u":"Prise en charge","t":"Connaître les principes de la prise en charge symptomatique de la diarrhée","q":"Quels sont les aliments à éviter dans la prise en charge symptomatique d'une diarrhée aiguë infectieuse et TIAC ?","a":"<ul><li>Les <strong>repas copieux</strong></li><li>Le <strong>lait</strong></li><li>Les <strong>crudités</strong></li><li>Les <strong>fibres</strong></li></ul>"},{"i":"e221ac3db5b0","n":176,"o":"176-12","u":"Prise en charge","t":"Connaître les principes de la prise en charge symptomatique de la diarrhée","q":"Quelle est la règle générale concernant l'alimentation dans la prise en charge symptomatique d'une diarrhée aiguë infectieuse et TIAC ?","a":"<p>Il convient de <strong>poursuivre les apports</strong> en adaptant le régime alimentaire.</p>"},{"i":"f22516a84b28","n":176,"o":"176-12","u":"Prise en charge","t":"Connaître les principes de la prise en charge symptomatique de la diarrhée","q":"Quand les anti-péristaltiques comme le lopéramide sont-ils contre-indiqués dans la diarrhée aiguë infectieuse et TIAC ?","a":"<p>Le lopéramide est contre-indiqué en cas de <strong>diarrhée sanglante (syndrome dysentérique)</strong>, de <strong>diarrhée fébrile</strong>, ou chez l’<strong>enfant de moins de 30 mois</strong>.</p>"},{"i":"09dcaf352a61","n":176,"o":"176-13","u":"Prise en charge","t":"Connaître les principes de l’antibiothérapie","q":"Quelles sont les situations où une antibiothérapie probabiliste est indiquée en cas de diarrhée aiguë infectieuse ?","a":"<p>Une antibiothérapie probabiliste est indiquée dans les situations suivantes :</p><ul><li><strong>Terrain à risque</strong> : âges extrêmes (< 3 mois, sujet âgé), immunodépression, drépanocytose, valvulopathie, anévrysme de l’aorte.</li><li>Diarrhée <strong>dysentérique fébrile</strong>.</li><li>Diarrhée <strong>cholériforme</strong> ou <strong>gastro-entéritique sévère</strong> (température &gt; 38,5 °C ou plus de 6 selles par jour).</li></ul>"},{"i":"48af37725df2","n":176,"o":"176-13","u":"Prise en charge","t":"Connaître les principes de l’antibiothérapie","q":"Quelle est l'antibiothérapie probabiliste de première intention pour une diarrhée aiguë infectieuse avec indication d'un traitement antibiotique, et quelle est sa durée habituelle ?","a":"<p>L'antibiothérapie probabiliste de première intention est :</p><ul><li>Par <strong>voie orale</strong> : <strong>azithromycine</strong> ou <strong>ciprofloxacine</strong> pendant <strong>1 à 3 jours</strong>.</li><li>En cas de voie orale impossible : <strong>ceftriaxone IV</strong>, à laquelle peut être associé le <strong>métronidazole IV</strong>.</li></ul><p>L'antibiothérapie est d'autant plus efficace si elle est débutée dans les <strong>48 heures</strong>. La durée est de <strong>1 à 7 jours</strong> en l'absence de bactériémie.</p>"},{"i":"bab135cb642c","n":176,"o":"176-13","u":"Prise en charge","t":"Connaître les principes de l’antibiothérapie","q":"Dans quel contexte clinique la prescription d'une antibiothérapie n'est-elle pas recommandée pour une diarrhée aiguë infectieuse ?","a":"<p>L'antibiothérapie n'est pas recommandée dans les cas suivants :</p><ul><li>Contexte épidémique évoquant une <strong>origine virale</strong>.</li><li>Diarrhée aiguës de type <strong>cholériforme</strong> ou <strong>gastro-entéritique non sévère</strong>, en l'absence de terrain à risque.</li></ul>"},{"i":"0dabdcef5c2c","n":176,"o":"176-14","u":"Prise en charge","t":"Connaître les éléments de prévention d’une diarrhée infectieuse","q":"En milieu hospitalier, quelles sont les précautions spécifiques pour prévenir la transmission des diarrhées infectieuses, notamment en cas d'infection à <i>Clostridioides difficile</i> ?","a":"<p>En milieu hospitalier, il faut appliquer des <strong>précautions complémentaires contact de type 1</strong> adaptées au germe. En cas d'infection à <i>Clostridioides difficile</i>, qui est un piège classique car ses spores sont résistantes, des <strong>précautions de type 2</strong> sont nécessaires, incluant un <strong>lavage des mains au savon doux avant le SHA</strong> et une <strong>désinfection des surfaces à l'eau de Javel</strong>.</p>"},{"i":"381be40f7047","n":176,"o":"176-14","u":"Prise en charge","t":"Connaître les éléments de prévention d’une diarrhée infectieuse","q":"Quelles sont les principales mesures d'hygiène alimentaire à respecter pour prévenir les diarrhées aiguës infectieuses et les TIAC ?","a":"<p>Les mesures d'hygiène alimentaire pour prévenir les diarrhées aiguës infectieuses incluent le <strong>respect de la chaîne du froid</strong>, l'application du principe de la <strong>« marche en avant »</strong> (aucun contact entre secteur propre et secteur souillé), le maintien d'une hygiène stricte sur les <strong>lieux d'abattage, de pêche et de récolte</strong>, ainsi que l'hygiène des transports.</p>"},{"i":"4644dd9151d8","n":176,"o":"176-14","u":"Prise en charge","t":"Connaître les éléments de prévention d’une diarrhée infectieuse","q":"Quelles sont les mesures d'hygiène individuelle essentielles pour prévenir la diarrhée aiguë infectieuse, dont la transmission est oro-fécale ?","a":"<p>Pour prévenir la diarrhée aiguë infectieuse par l'hygiène individuelle, il est essentiel de pratiquer le <strong>lavage des mains au SHA</strong> (solution hydro-alcoolique) et d'assurer une <strong>désinfection régulière des sanitaires</strong>.</p>"},{"i":"bf29d792f4ac","n":176,"o":"176-14","u":"Prise en charge","t":"Connaître les éléments de prévention d’une diarrhée infectieuse","q":"Quel rôle joue la vaccination dans la prévention des diarrhées aiguës infectieuses, notamment chez l'enfant ?","a":"<p>La vaccination est un axe de prévention important, notamment avec le <strong>vaccin contre le Rotavirus</strong>. Ce vaccin est recommandé chez le nourrisson, car le Rotavirus est la <strong>première cause de diarrhée grave avec déshydratation chez l'enfant de moins de 5 ans</strong>.</p>"},{"i":"cf09832ebcd2","n":176,"o":"176-14","u":"Prise en charge","t":"Connaître les éléments de prévention d’une diarrhée infectieuse","q":"En restauration collective, quelles sont les mesures de surveillance du personnel et de contrôle microbiologique des aliments pour prévenir les TIAC ?","a":"<p>En restauration collective, il faut veiller à l'<strong>éviction du personnel présentant une infection cutanée, pharyngée ou digestive</strong>. Des <strong>contrôles microbiologiques</strong> sont également mis en place, avec des analyses systématiques des aliments par l'ARS, la DSV et la DCCRF.</p>"},{"i":"373acc4e824b","n":176,"o":"176-15","u":"Définition","t":"Connaître la définition d’une toxi-infection alimentaire collective","q":"Quels sont les principaux modes de contamination lors d'une TIAC et les bactéries associées ?","a":"<p>La contamination se fait par la consommation d'aliments contaminés par des bactéries ou leurs toxines. On distingue :</p><ul><li>La <strong>toxinogénèse dans l'aliment</strong> : notamment par <strong><em>Staphylococcus aureus</em></strong>, la toxine thermostable de <strong><em>Bacillus cereus</em></strong>, ou <strong><em>Clostridium botulinum</em></strong>.</li><li>La <strong>toxinogénèse dans la lumière digestive</strong> : par exemple, la toxine thermolabile de <strong><em>Bacillus cereus</em></strong>.</li></ul>"},{"i":"6afb1335181d","n":176,"o":"176-15","u":"Définition","t":"Connaître la définition d’une toxi-infection alimentaire collective","q":"Comment doit être gérée la déclaration d'une suspicion de TIAC ?","a":"<p>La TIAC est une <strong>Maladie à Déclaration Obligatoire (MDO)</strong>. Elle doit être déclarée <strong>par téléphone à l'ARS</strong> (ou au service vétérinaire d'hygiène alimentaire à défaut). Il est impératif de <strong>conserver les restes alimentaires des 3 derniers jours au réfrigérateur</strong> (jamais au congélateur) pour analyse microbiologique.</p>"},{"i":"bcad813ee6ba","n":176,"o":"176-15","u":"Définition","t":"Connaître la définition d’une toxi-infection alimentaire collective","q":"Quels sont les aliments les plus souvent en cause et les facteurs favorisants d'une TIAC ?","a":"<p>Les aliments les plus souvent en cause sont la <strong>volaille</strong> et les <strong>aliments à base d'œufs</strong>. Les principaux facteurs favorisants sont :</p><ul><li>Le <strong>non-respect de la chaîne du froid</strong>.</li><li>Des <strong>erreurs dans le processus de préparation</strong> des aliments.</li><li>Un <strong>délai trop important</strong> entre la préparation et la consommation.</li></ul>"},{"i":"e5c541725187","n":176,"o":"176-15","u":"Définition","t":"Connaître la définition d’une toxi-infection alimentaire collective","q":"Qu'est-ce qu'une toxi-infection alimentaire collective (TIAC) ?","a":"<p>Une toxi-infection alimentaire collective (TIAC) se définit par la survenue d'<strong>au moins 2 cas</strong> de symptomatologie générale digestive, typiquement une <strong>diarrhée d'apparition brutale</strong>, avec une même <strong>origine alimentaire probable</strong>.</p>"},{"i":"7be43919e9a7","n":176,"o":"176-16","u":"Identifier une urgence","t":"Savoir identifier les situations à prendre en charge en urgence","q":"Quels sont les principales situations d'urgence à identifier d'emblée devant une diarrhée aiguë infectieuse ou une TIAC, nécessitant une prise en charge rapide ?","a":"<p>Les quatre situations d'urgence majeures à identifier sont :</p><ul><li>Un état de <strong>sepsis</strong>.</li><li>Une <strong>déshydratation</strong> sévère.</li><li>Un <strong>syndrome occlusif</strong>.</li><li>Une diarrhée fébrile au retour d'un <strong>pays d'endémie palustre</strong>.</li></ul>"},{"i":"91369d43cb54","n":176,"o":"176-16","u":"Identifier une urgence","t":"Savoir identifier les situations à prendre en charge en urgence","q":"Quels sont les critères cliniques et contextuels justifiant une hospitalisation en urgence face à une diarrhée aiguë infectieuse ou une TIAC ?","a":"<p>Les critères justifiant une hospitalisation en urgence sont :</p><ul><li>Âge <strong>inférieur à 3 mois</strong>.</li><li><strong>Déshydratation supérieure à 8 %</strong> du poids corporel.</li><li>Présence d'un <strong>collapsus</strong>.</li><li>Présence de <strong>signes de sepsis</strong>.</li><li>Présence d'un <strong>syndrome occlusif</strong>.</li><li>Diarrhée fébrile au retour d'un <strong>pays d'endémie palustre</strong>.</li><li>Vomissements rendant la <strong>réhydratation orale impossible</strong>.</li><li>Décompensation d'une <strong>comorbidité</strong> (maladie chronique).</li><li>Situation d'<strong>isolement</strong> ou de <strong>milieu social défavorisé</strong>.</li></ul>"},{"i":"04e50d43243f","n":176,"o":"176-17","u":"Identifier une urgence","t":"Connaître la prescription d’une réhydratation orale et intraveineuse ; connaître les traitements symptomatiques de la diarrhée aiguë","q":"Quels sont les composants essentiels des Sels de Réhydratation Orale (SRO) pour une diarrhée aiguë infectieuse ?","a":"<p>Les SRO sont composés de <strong>sodium</strong>, de <strong>glucose</strong>, de <strong>potassium</strong> et d'un <strong>agent alcalinisant</strong>.</p>"},{"i":"1d0c1af43f23","n":176,"o":"176-17","u":"Identifier une urgence","t":"Connaître la prescription d’une réhydratation orale et intraveineuse ; connaître les traitements symptomatiques de la diarrhée aiguë","q":"Dans quel contexte clinique la prescription d'une réhydratation orale (SRO) est-elle envisagée pour une diarrhée aiguë infectieuse ?","a":"<p>La réhydratation orale avec des <strong>Sels de Réhydratation Orale (SRO)</strong> est indiquée <strong>dès que possible</strong>, en complément d'une alimentation salée, lorsque la situation ne relève pas d'une réhydratation intraveineuse.</p>"},{"i":"47afa4e4694a","n":176,"o":"176-17","u":"Identifier une urgence","t":"Connaître la prescription d’une réhydratation orale et intraveineuse ; connaître les traitements symptomatiques de la diarrhée aiguë","q":"Quel est le protocole de perfusion intraveineuse recommandé en cas de déshydratation sévère liée à une diarrhée aiguë infectieuse ?","a":"<p>Le protocole consiste à perfuser <strong>50 % des pertes</strong> estimées sur les <strong>6 premières heures</strong>, puis les <strong>50 % restants sur les 18 heures suivantes</strong>, avec une <strong>surveillance pondérale quotidienne</strong>.</p>"},{"i":"749cc0dfca3c","n":176,"o":"176-17","u":"Identifier une urgence","t":"Connaître la prescription d’une réhydratation orale et intraveineuse ; connaître les traitements symptomatiques de la diarrhée aiguë","q":"Quelles sont les indications de la réhydratation intraveineuse en cas de diarrhée aiguë infectieuse ?","a":"<p>La réhydratation intraveineuse est indiquée en cas de :</p><ul><li><strong>Déshydratation ≥ 8 % du poids</strong></li><li><strong>Vomissements importants</strong></li><li>Présence de <strong>signes de gravité</strong></li><li>Présence de <strong>troubles ioniques</strong> (notamment la kaliémie)</li></ul>"},{"i":"c41b98c21626","n":176,"o":"176-17","u":"Identifier une urgence","t":"Connaître la prescription d’une réhydratation orale et intraveineuse ; connaître les traitements symptomatiques de la diarrhée aiguë","q":"Quels sont les principaux traitements symptomatiques utilisables dans la diarrhée aiguë infectieuse ?","a":"<p>Les traitements symptomatiques qui complètent la prise en charge sont le <strong>racécadotril</strong> et la <strong>diosmectite</strong>.</p>"},{"i":"8706c4396421","n":176,"o":"176-2","u":"Physiopathologie","t":"Connaître les principales causes, mécanismes et modes de transmission des diarrhées","q":"Quels sont les principaux modes de transmission des diarrhées aiguës infectieuses ?","a":"<p>Les principaux modes de transmission sont :</p><ul><li>L'<strong>eau</strong> ou les <strong>aliments contaminés</strong>.</li><li>Le <strong>manuportage</strong> d'un individu à l'autre.</li></ul>"},{"i":"9d6306584c48","n":176,"o":"176-2","u":"Physiopathologie","t":"Connaître les principales causes, mécanismes et modes de transmission des diarrhées","q":"Quels sont les principaux germes viraux responsables de diarrhée aiguë infectieuse, et leur particularité chez l'enfant ?","a":"<p>Les principaux germes viraux sont le <strong>Norovirus</strong> et le <strong>Rotavirus</strong>. Le Rotavirus est particulièrement fréquent chez l'enfant.</p>"},{"i":"a4b5485681fe","n":176,"o":"176-2","u":"Physiopathologie","t":"Connaître les principales causes, mécanismes et modes de transmission des diarrhées","q":"Quelles sont les principales bactéries responsables de diarrhée aiguë infectieuse ?","a":"<ul><li><strong>Campylobacter</strong></li><li><strong>Salmonella</strong></li><li><strong>Shigella</strong></li><li><strong>Yersinia</strong></li><li><strong>E. coli entéro-invasif</strong> ou <strong>entéro-hémorragique</strong></li></ul>"},{"i":"aabeee580999","n":176,"o":"176-2","u":"Physiopathologie","t":"Connaître les principales causes, mécanismes et modes de transmission des diarrhées","q":"Quels sont les principaux parasites responsables de diarrhée aiguë infectieuse et quelle est leur particularité en termes de durée ?","a":"<p>Les principaux parasites sont <strong>Giardiose</strong>, <strong>Cryptosporidiose</strong> et <strong>Entamoeba histolytica</strong>. Les parasitoses sont la cause infectieuse majoritaire des diarrhées qui durent <strong>plus de 14 jours</strong>.</p>"},{"i":"b1b3c7d4b08d","n":176,"o":"176-2","u":"Physiopathologie","t":"Connaître les principales causes, mécanismes et modes de transmission des diarrhées","q":"Quels sont les deux grands mécanismes physiopathologiques des diarrhées aiguës infectieuses ?","a":"<p>Il existe deux grands mécanismes :</p><ul><li>Le mécanisme <strong>entéro-invasif</strong> : la bactérie envahit l'épithélium intestinal.</li><li>Le mécanisme <strong>sécrétoire / toxinogène</strong> : une toxine déclenche une hypersécrétion sans invasion de l'épithélium.</li></ul>"},{"i":"e0b0bdb62299","n":176,"o":"176-2","u":"Physiopathologie","t":"Connaître les principales causes, mécanismes et modes de transmission des diarrhées","q":"Quel est le piège diagnostique classique concernant une diarrhée aiguë fébrile au retour de voyage ?","a":"<p>Une diarrhée aiguë fébrile ne témoigne pas systématiquement d'une infection entéro-colique. Tout <strong>sepsis</strong> peut s'accompagner d'une accélération du transit. Il faut notamment penser au <strong>paludisme</strong> au retour de voyage.</p>"},{"i":"1c0267a27090","n":176,"o":"176-3","u":"Identifier une urgence","t":"Identifier les situations à prendre en charge en urgence","q":"Quels sont les repères cliniques permettant de suspecter un sepsis chez un patient présentant une diarrhée aiguë infectieuse ?","a":"<p>Les repères cliniques pour suspecter un sepsis sont un score <strong>qSOFA ≥ 2</strong>, caractérisé par au moins deux des critères suivants :</p><ul><li>Fréquence respiratoire ≥ 22/min.</li><li>Pression artérielle systolique ≤ 100 mmHg.</li><li>Score de Glasgow < 15.</li></ul><p>Certains <strong>terrains à risque</strong> augmentent également la suspicion : valvulopathie, sujet âgé, drépanocytose, et immunodépression (VIH avec CD4 < 200, chimiothérapie, déficit congénital).</p>"},{"i":"5b4e594eebd9","n":176,"o":"176-3","u":"Identifier une urgence","t":"Identifier les situations à prendre en charge en urgence","q":"Devant une diarrhée aiguë infectieuse associée à un syndrome occlusif fonctionnel du côlon, quelle est l'attitude immédiate ?","a":"<p>Face à un syndrome occlusif fonctionnel du côlon (sans obstacle) dû à une colite grave (ex: <em>Salmonella</em>, <em>Shigella</em>, <em>C. difficile</em>), une hypokaliémie ou la prise de lopéramide, la conduite à tenir immédiate est de réaliser un <strong>TDM abdomino-pelvienne injectée</strong>. L'objectif est d'éliminer formellement une <strong>urgence chirurgicale</strong> sous-jacente.</p>"},{"i":"7599410efc5d","n":176,"o":"176-3","u":"Identifier une urgence","t":"Identifier les situations à prendre en charge en urgence","q":"Quels sont les principaux terrains à risque de déshydratation sévère en cas de diarrhée aiguë ?","a":"<p>Les sujets à risque de déshydratation sévère sont :</p><ul><li>Le <strong>nourrisson</strong>.</li><li>La <strong>personne âgée dépendante</strong>.</li><li>Le patient <strong>polymédiqué</strong>, notamment sous diurétiques.</li></ul>"},{"i":"799174713d40","n":176,"o":"176-3","u":"Identifier une urgence","t":"Identifier les situations à prendre en charge en urgence","q":"Quelle est la sémiologie de la déshydratation intra-cellulaire et extra-cellulaire chez un patient souffrant de diarrhée aiguë ?","a":"<p>La déshydratation se manifeste par deux sémiologies distinctes :</p><ul><li><strong>Déshydratation intracellulaire</strong> : <ul><li><strong>Soif</strong> intense.</li><li>Sécheresse des muqueuses.</li><li>Fièvre, troubles de conscience.</li></ul></li><li><strong>Déshydratation extracellulaire</strong> : <ul><li>Tachycardie, hypotension, <strong>oligurie</strong> (signes de gravité).</li><li>Pli cutané persistant.</li><li>Cernes, yeux creusés.</li></ul></li></ul>"},{"i":"d68a05f5c3fd","n":176,"o":"176-3","u":"Identifier une urgence","t":"Identifier les situations à prendre en charge en urgence","q":"Quelle est la démarche diagnostique systématique à adopter devant une diarrhée aiguë infectieuse chez un patient revenant d'une zone d'endémie palustre ?","a":"<p>Chez un patient revenant d'une zone d'endémie palustre et présentant une diarrhée aiguë, il est impératif d'éliminer un <strong>accès palustre</strong>. Pour cela, des examens systématiques sont requis : <strong>frottis sanguin</strong> et <strong>goutte épaisse</strong>.</p>"},{"i":"f0e80d02c541","n":176,"o":"176-3","u":"Identifier une urgence","t":"Identifier les situations à prendre en charge en urgence","q":"Quels sont les quatre types de situations devant faire suspecter une urgence devant une diarrhée aiguë infectieuse ?","a":"<p>Les quatre situations devant faire suspecter une urgence sont :</p><ul><li>Un <strong>sepsis</strong>.</li><li>Une <strong>déshydratation</strong> sévère.</li><li>Un <strong>syndrome occlusif</strong> (particulièrement une occlusion fonctionnelle colique).</li><li>Un <strong>retour de zone d'endémie palustre</strong>.</li></ul>"},{"i":"520b0050c7d2","n":176,"o":"176-4","u":"Diagnostic positif","t":"Connaître les éléments d’orientation étiologique d’une diarrhée aiguë infectieuse","q":"Quels sont les principaux éléments contextuels à rechercher pour orienter l'étiologie d'une diarrhée aiguë infectieuse ?","a":"<p>Les principaux éléments contextuels comprennent :</p><ul><li>Un <strong>voyage récent</strong> (suspicion d'infection tropicale ou parasitose).</li><li>Une <strong>antibiothérapie récente</strong> (< 3 mois) (suspicion de <em>Clostridioides difficile</em>).</li><li>Des <strong>cas groupés</strong> (suspicion de Toxi-Infection Alimentaire Collective - TIAC).</li><li>Un <strong>contage ou un contexte épidémique</strong> (suspicion de gastro-entérite virale).</li></ul>"},{"i":"7f31260d1b9a","n":176,"o":"176-4","u":"Diagnostic positif","t":"Connaître les éléments d’orientation étiologique d’une diarrhée aiguë infectieuse","q":"Quels sont les éléments concernant le terrain et les signes associés à rechercher pour l'orientation étiologique d'une diarrhée aiguë infectieuse ?","a":"<p>Concernant le terrain et les signes associés, il faut rechercher :</p><ul><li>Le <strong>terrain du patient</strong> : <strong>âge avancé</strong>, présence de <strong>comorbidités</strong> (IRC, MICI), <strong>immunodépression</strong>.</li><li>Les <strong>signes associés</strong> : <strong>fièvre</strong>, <strong>douleurs abdominales</strong>, <strong>ténesme</strong>, <strong>épreintes</strong>, <strong>vomissements</strong>, et les éventuels <strong>signes extradigestifs</strong> (arthralgies, éruption cutanée).</li></ul>"},{"i":"fc2584e6000d","n":176,"o":"176-4","u":"Diagnostic positif","t":"Connaître les éléments d’orientation étiologique d’une diarrhée aiguë infectieuse","q":"Quelles caractéristiques de la diarrhée orientent vers une étiologie particulière en cas de diarrhée aiguë infectieuse ?","a":"<p>Les caractéristiques à prendre en compte sont :</p><ul><li>La <strong>durée</strong> : aiguë (< 14 jours), persistante (14-30 jours), chronique (> 1 mois).</li><li>Le <strong>nombre de selles</strong>: une fréquence > 6/jour est un critère de sévérité.</li><li>L'<strong>aspect des selles</strong>: présence de <strong>glaires ou de sang</strong> oriente vers une étiologie invasive.</li></ul>"},{"i":"06247241763a","n":176,"o":"176-5","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’un syndrome cholériforme, dysentérique et gastroentéritique","q":"Comment se caractérise cliniquement un syndrome cholériforme lors d'une diarrhée aiguë infectieuse ?","a":"<p>Le syndrome cholériforme se caractérise par une <strong>diarrhée hydrique, aqueuse, profuse</strong>, souvent décrite comme de « l'eau de riz ». Les vomissements sont inconstants et la fièvre est habituellement <strong>absente</strong>. Le risque évolutif principal est la <strong>déshydratation</strong>.</p>"},{"i":"479ab8c53bc4","n":176,"o":"176-5","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’un syndrome cholériforme, dysentérique et gastroentéritique","q":"Quel est le mécanisme physiopathologique et les agents pathogènes typiques du syndrome cholériforme ?","a":"<p>Le mécanisme est <strong>sécrétoire</strong>, via la production de toxines, affectant principalement l'<strong>intestin grêle</strong>. Les agents pathogènes typiques incluent :</p><ul><li>Virus : Norovirus, Rotavirus, Adénovirus</li><li>Bactéries toxi-infectieuses : <em>Staphylococcus aureus</em>, <em>Bacillus cereus</em>, <em>Clostridium perfringens</em></li><li>Entérobactéries : <em>E. coli</em> entéro-toxinogène (ETEC)</li><li>Vibrion : <em>Vibrio cholerae</em></li><li>Parasite : <em>Cryptosporidium</em></li></ul>"},{"i":"5d6c869245d5","n":176,"o":"176-5","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’un syndrome cholériforme, dysentérique et gastroentéritique","q":"Quels sont le mécanisme et les principaux agents pathogènes impliqués dans un syndrome dysentérique ?","a":"<p>Le mécanisme du syndrome dysentérique est <strong>entéro-invasif</strong>, entraînant une destruction épithéliale, principalement au niveau du <strong>côlon ou de l'iléon-côlon</strong>. Les agents pathogènes clés sont :</p><ul><li><em>Shigella</em></li><li><em>E. coli</em> entéro-hémorragique (ECEH)</li><li><em>E. coli</em> entéro-invasif (ECIA)</li><li><em>Entamoeba histolytica</em> (amibiase)</li></ul>"},{"i":"72908943bb06","n":176,"o":"176-5","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’un syndrome cholériforme, dysentérique et gastroentéritique","q":"Quels mécanismes et agents pathogènes sont associés au syndrome gastro-entéritique ?","a":"<p>Le mécanisme est <strong>entéro-invasif</strong>, caractérisé par une traversée de la muqueuse sans destruction épithéliale majeure, au niveau de l'<strong>intestin grêle</strong>. Les agents pathogènes typiques incluent :</p><ul><li><em>Campylobacter</em></li><li><em>Salmonella</em> non Typhi</li><li><em>Yersinia</em></li><li><em>E. coli</em> entéro-pathogène (EPEC)</li></ul>"},{"i":"904efdd6afe0","n":176,"o":"176-5","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’un syndrome cholériforme, dysentérique et gastroentéritique","q":"Comment se manifeste un syndrome dysentérique lors d'une diarrhée aiguë infectieuse ?","a":"<p>Le syndrome dysentérique se manifeste par des <strong>selles afécales, glaireuses et sanglantes</strong>. On note de plus un <strong>syndrome rectal</strong> avec épreintes, ténesme et faux besoins. La <strong>fièvre est présente</strong>, sauf en cas d'amibiase colique qui est afébrile. Le risque évolutif est celui d'un <strong>sepsis, d'une occlusion ou d'une colectasie</strong>.</p>"},{"i":"dbf30d4260f7","n":176,"o":"176-5","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’un syndrome cholériforme, dysentérique et gastroentéritique","q":"Décrivez les caractéristiques cliniques d'un syndrome gastro-entéritique dans le cadre d'une diarrhée aiguë infectieuse.","a":"<p>Le syndrome gastro-entéritique se caractérise par une <strong>diarrhée banale et aspécifique</strong>, des <strong>douleurs abdominales diffuses</strong> et des <strong>vomissements</strong>. La <strong>fièvre est fréquente</strong>. Le risque évolutif est le <strong>sepsis ou la bactériémie</strong>, particulièrement chez les patients immunodéprimés ou drépanocytaires.</p>"},{"i":"02f5b8747155","n":176,"o":"176-7","u":"Examens complémentaires","t":"Connaître les principaux examens complémentaires à visée étiologique","q":"Quand faut-il réaliser des hémocultures face à une diarrhée aiguë infectieuse ?","a":"<p>Des hémocultures doivent être réalisées en présence d'une <strong>fièvre</strong> accompagnant la diarrhée aiguë infectieuse, afin de rechercher une éventuelle bactériémie ou septicémie.</p>"},{"i":"052202c3abf1","n":176,"o":"176-7","u":"Examens complémentaires","t":"Connaître les principaux examens complémentaires à visée étiologique","q":"Comment doit être recherchée une infection à Clostridioides difficile en cas de diarrhée aiguë, et par quels moyens ?","a":"<p>La recherche de <em>Clostridioides difficile</em> (anciennement <em>Clostridium difficile</em>) nécessite une demande explicite au laboratoire et n'est pas incluse dans une coproculture standard. Elle vise spécifiquement les <strong>toxines A/B de <em>C. difficile</em></strong> et est réalisée par des techniques comme la <strong>PCR</strong> ou l'<strong>ELISA</strong>.</p>"},{"i":"3fb24360bdc2","n":176,"o":"176-7","u":"Examens complémentaires","t":"Connaître les principaux examens complémentaires à visée étiologique","q":"Quel est le piège classique concernant l'interprétation des résultats de coproculture pour E. coli, S. aureus et C. albicans ?","a":"<p>Le piège classique est qu'en coproculture, la présence d'<strong><em>E. coli</em> non typé</strong>, <strong><em>S. aureus</em></strong> et <strong><em>C. albicans</em></strong> correspond le plus souvent à un <strong>portage sain</strong>. Leur présence n'affirme donc pas l'étiologie de la diarrhée. La recherche d'autres germes spécifiques (comme <em>C. difficile</em> et ses toxines, ou <em>EHEC</em>) doit être explicitement précisée au microbiologiste si suspectée cliniquement.</p>"},{"i":"4e1d9cc99217","n":176,"o":"176-7","u":"Examens complémentaires","t":"Connaître les principaux examens complémentaires à visée étiologique","q":"Dans quels contextes est indiquée la recherche de virus dans les selles pour une diarrhée aiguë infectieuse ?","a":"<p>La recherche de virus dans les selles est indiquée principalement lors d'<strong>épidémies en collectivité</strong> et chez les <strong>patients immunodéprimés</strong> présentant une diarrhée.</p>"},{"i":"5c4645d207d2","n":176,"o":"176-7","u":"Examens complémentaires","t":"Connaître les principaux examens complémentaires à visée étiologique","q":"Dans quel contexte clinique la coproculture est-elle indiquée face à une diarrhée aiguë infectieuse et quelles sont les bactéries recherchées de routine ?","a":"<p>La coproculture est indiquée dans les situations suivantes :</p><ul><li>Diarrhée fébrile ou toxi-infection alimentaire collective (TIAC) fébrile.</li><li>Retour des tropiques.</li><li>Présence de signes de gravité.</li><li>Patient immunodéprimé.</li></ul><p>Elle recherche de routine : <strong>Salmonella</strong>, <strong>Shigella</strong>, <strong>Yersinia</strong>, <strong>Campylobacter</strong>. Elle doit être réalisée avant toute antibiothérapie.</p>"},{"i":"6fb51ced3b6c","n":176,"o":"176-7","u":"Examens complémentaires","t":"Connaître les principaux examens complémentaires à visée étiologique","q":"Quand doit-on envisager un écouvillon rectal et quelles sont les étiologies à rechercher en cas de rectite/sigmoïdite ?","a":"<p>Un écouvillon rectal est indiqué en cas de <strong>rectite</strong> ou de <strong>recto-sigmoïdite</strong>. Il faut alors évoquer une <strong>infection sexuellement transmissible (IST)</strong> et rechercher spécifiquement :</p><ul><li>Sérologie syphilis.</li><li>PCR Chlamydiae.</li><li>PCR gonocoque.</li><li>Virologie HSV (virus Herpes simplex).</li></ul>"},{"i":"1eacd27a8794","n":176,"o":"176-9","u":"Examens complémentaires","t":"Connaître les principaux examens complémentaires évaluant le retentissement","q":"Quels sont les examens complémentaires à réaliser pour évaluer le retentissement d'une déshydratation au cours d'une diarrhée aiguë infectieuse ?","a":"<p>En cas de déshydratation, il convient de réaliser :</p><ul><li>Une <strong>Numération Formule Sanguine (NFS)</strong></li><li>Un <strong>ionogramme sanguin</strong></li><li>Une <strong>créatininémie</strong></li><li>Une <strong>gazométrie</strong> (sangine)</li></ul>"},{"i":"902680c0e732","n":176,"o":"176-9","u":"Examens complémentaires","t":"Connaître les principaux examens complémentaires évaluant le retentissement","q":"Quel examen complémentaire est indiqué en cas de fièvre associée à une défense abdominale au cours d'une diarrhée aiguë infectieuse, pour évaluer le retentissement ?","a":"<p>En cas de fièvre associée à une défense abdominale, il faut réaliser un <strong>Scanner abdomino-pelvien injecté</strong>.</p>"}]};